observations.query:
BEGIN READ ONLY;
SELECT json_build_object('observedAtUTC',timezone('UTC',clock_timestamp()),'database',current_database(),'dbUser',current_user,'serverAddress',inet_server_addr(),'serverPort',inet_server_port(),'transactionReadOnly',current_setting('transaction_read_only'));
SELECT coalesce(json_agg(row_to_json(p)), '[]'::json) FROM (SELECT id,agent_id,display_name,status,principal_type,owner_user_id,external_ref,disabled_at,created_at FROM machine_principals WHERE agent_id IN ('release-captain-agent-core-20261107','agt_release-captain-agent-core-20261107') OR external_ref IN ('release-captain-agent-core-20261107','agt_release-captain-agent-core-20261107') OR display_name='release-captain-agent-core-20261107' ORDER BY id) p;
SELECT json_agg(row_to_json(e)) FROM (SELECT n.nspname AS schema,t.typname AS enum_name,e.enumlabel FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE t.typname='PrincipalType' ORDER BY e.enumsortorder) e;
SELECT json_agg(row_to_json(i)) FROM (SELECT indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename='machine_principals' AND indexdef LIKE 'CREATE UNIQUE%') i;
COMMIT;
